#!/bin/bash
exec python3 /app/bandit.pyc "$@"

(exit_code=0)

function.arguments:
{"command": "python3 -c "
with open('/app/bandit.pyc', 'r', encoding='latin-1') as f:
    content = f.read()

# Find all lines containing 'arms' or '10'
lines = content.split('\n')
for line in lines:
    if 'arms' in line.lower() or '10' in line or 'horizon' in line:
        print(line[:500])
""}
